import time
import statistics

def benchmark_latency(fn, iterations=1000):
    """Measure p50, p95, and p99 latency of a function call."""
    samples = []
    for _ in range(iterations):
        start = time.perf_counter()
        fn()
        samples.append((time.perf_counter() - start) * 1000)  # ms
    samples.sort()
    return {
        'p50': samples[int(0.50 * len(samples))],
        'p95': samples[int(0.95 * len(samples))],
        'p99': samples[int(0.99 * len(samples))],
    }

import time

def measure_throughput(fn, duration_seconds=10):
    """Count how many times fn() completes in the given window."""
    count = 0
    deadline = time.monotonic() + duration_seconds
    while time.monotonic() < deadline:
        fn()
        count += 1
    return count / duration_seconds  # operations per second

